import pytest

# The function under test
def zip_dicts(*dicts) -> dict:
    keys = set().union(*dicts)
    return {k: [d.get(k) for d in dicts] for k in keys}


class TestZipDicts:
    """Unit tests for zip_dicts function."""

    # --- Happy Path ---
    def test_two_dicts_with_overlap(self):
        d1 = {'a': 1, 'b': 2}
        d2 = {'b': 3, 'c': 4}
        result = zip_dicts(d1, d2)
        expected = {
            'a': [1, None],
            'b': [2, 3],
            'c': [None, 4]
        }
        assert result == expected

    def test_multiple_dicts_disjoint_keys(self):
        d1 = {'a': 1}
        d2 = {'b': 2}
        d3 = {'c': 3}
        result = zip_dicts(d1, d2, d3)
        expected = {
            'a': [1, None, None],
            'b': [None, 2, None],
            'c': [None, None, 3]
        }
        assert result == expected

    def test_single_dict(self):
        d = {'x': 10, 'y': 20}
        result = zip_dicts(d)
        expected = {'x': [10], 'y': [20]}
        assert result == expected

    # --- Edge Cases ---
    def test_no_arguments(self):
        result = zip_dicts()
        assert result == {}

    def test_empty_dicts(self):
        d1 = {}
        d2 = {'a': 1}
        result = zip_dicts(d1, d2)
        expected = {'a': [None, 1]}
        assert result == expected

    def test_all_empty_dicts(self):
        result = zip_dicts({}, {}, {})
        assert result == {}

    def test_none_values(self):
        d1 = {'a': None}
        d2 = {'a': 1, 'b': None}
        result = zip_dicts(d1, d2)
        expected = {'a': [None, 1], 'b': [None, None]}
        assert result == expected

    def test_various_key_types(self):
        d1 = {1: 'int', 'str': 'string', (1, 2): 'tuple'}
        d2 = {1: 'int2', 'str2': 'string2'}
        result = zip_dicts(d1, d2)
        expected = {
            1: ['int', 'int2'],
            'str': ['string', None],
            (1, 2): ['tuple', None],
            'str2': [None, 'string2']
        }
        assert result == expected

    def test_large_number_of_dicts(self):
        dicts = [{'a': i} for i in range(100)]
        result = zip_dicts(*dicts)
        assert result == {'a': list(range(100))}

    # --- Error Cases ---
    def test_non_iterable_argument_raises_type_error(self):
        with pytest.raises(TypeError):
            zip_dicts(1)

    def test_iterable_with_unhashable_elements_raises_type_error(self):
        with pytest.raises(TypeError):
            zip_dicts([[]])  # list elements are unhashable

    def test_mixed_valid_and_invalid_raises_type_error(self):
        with pytest.raises(TypeError):
            zip_dicts({'a': 1}, 2)
